class Solution {
public:
 int earliestFullBloom(vector<int>& plantTime,vector<int>& growTime){
  int n=plantTime.size();vector<int> order(n);iota(order.begin(),order.end(),0);
  sort(order.begin(),order.end(),[&](int a,int b){return growTime[a]>growTime[b];});
  int day=0,ans=0;for(int i:order){day+=plantTime[i];ans=max(ans,day+growTime[i]);}
  return ans;
 }
};
